const QM_OFFSETS: [usize; 19] = [
    0, 16, 80, 336, 336, 1360, 1392, 1424, 1552, 1680, 2192, 336, 336, 2704, 2768, 2832, 3088,
    1680, 2192,
];
const QM_TOTAL_SIZE: usize = 3344;

pub fn quantizer_matrix_value(
    level: u8,
    chroma: bool,
    size: TxSize,
    coefficient: usize,
) -> Result<u8, Error> {
    if level >= 15 {
        return Err(Error::InvalidObu);
    }
    let (width, height) = size.dimensions();
    let count = usize::from(width.min(32))
        .checked_mul(usize::from(height.min(32)))
        .ok_or(Error::LimitExceeded)?;
    if coefficient >= count {
        return Err(Error::InvalidObu);
    }
    let matrix = usize::from(level)
        .checked_mul(2)
        .and_then(|value| value.checked_add(usize::from(chroma)))
        .ok_or(Error::LimitExceeded)?;
    let index = matrix
        .checked_mul(QM_TOTAL_SIZE)
        .and_then(|value| value.checked_add(QM_OFFSETS[size as usize]))
        .and_then(|value| value.checked_add(coefficient))
        .ok_or(Error::LimitExceeded)?;
    decode_matrix_byte(index)
}

pub fn write_quantizer_matrix(
    level: u8,
    chroma: bool,
    size: TxSize,
    output: &mut [u8],
) -> Result<usize, Error> {
    let (width, height) = size.dimensions();
    let count = usize::from(width.min(32))
        .checked_mul(usize::from(height.min(32)))
        .ok_or(Error::LimitExceeded)?;
    if output.len() < count {
        return Err(Error::InvalidObu);
    }
    for (coefficient, value) in output[..count].iter_mut().enumerate() {
        *value = quantizer_matrix_value(level, chroma, size, coefficient)?;
    }
    Ok(count)
}

pub fn write_selected_quantizer_matrix(
    quantization: &Quantization,
    lossless: bool,
    plane: u8,
    tx_type: TxType,
    size: TxSize,
    output: &mut [u8],
) -> Result<Option<usize>, Error> {
    if plane >= 3 {
        return Err(Error::InvalidObu);
    }
    if !quantization.using_qmatrix || lossless || (tx_type as u8) >= TxType::Identity as u8 {
        return Ok(None);
    }
    let level = match plane {
        0 => quantization.qm_y,
        1 => quantization.qm_u,
        _ => quantization.qm_v,
    };
    if level >= 15 {
        return Ok(None);
    }
    write_quantizer_matrix(level, plane > 0, size, output).map(Some)
}

fn decode_matrix_byte(index: usize) -> Result<u8, Error> {
    const DECODED_LENGTH: usize = 100_320;
    if index >= DECODED_LENGTH {
        return Err(Error::InvalidObu);
    }
    let quartet = (index / 3).checked_mul(4).ok_or(Error::LimitExceeded)?;
    let a = u32::from(base64_value(QUANTIZER_MATRIX_B64[quartet])?);
    let b = u32::from(base64_value(QUANTIZER_MATRIX_B64[quartet + 1])?);
    let c = u32::from(base64_value(QUANTIZER_MATRIX_B64[quartet + 2])?);
    let d = u32::from(base64_value(QUANTIZER_MATRIX_B64[quartet + 3])?);
    let packed = (a << 18) | (b << 12) | (c << 6) | d;
    Ok(match index % 3 {
        0 => (packed >> 16) as u8,
        1 => (packed >> 8) as u8,
        _ => packed as u8,
    })
}

const fn base64_value(byte: u8) -> Result<u8, Error> {
    match byte {
        b'A'..=b'Z' => Ok(byte - b'A'),
        b'a'..=b'z' => Ok(byte - b'a' + 26),
        b'0'..=b'9' => Ok(byte - b'0' + 52),
        b'+' => Ok(62),
        b'/' => Ok(63),
        _ => Err(Error::InvalidObu),
    }
}

pub fn dc_quantizer(bit_depth: u8, qindex: i16) -> Result<u16, Error> {
    Ok(DC_QLOOKUP[bit_depth_index(bit_depth)?][usize::from(qindex.clamp(0, 255) as u8)])
}

pub fn ac_quantizer(bit_depth: u8, qindex: i16) -> Result<u16, Error> {
    Ok(AC_QLOOKUP[bit_depth_index(bit_depth)?][usize::from(qindex.clamp(0, 255) as u8)])
}

const fn bit_depth_index(bit_depth: u8) -> Result<usize, Error> {
    match bit_depth {
        8 => Ok(0),
        10 => Ok(1),
        12 => Ok(2),
        _ => Err(Error::InvalidObu),
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DequantConfig<'a> {
    pub size: TxSize,
    pub bit_depth: u8,
    pub dc_quantizer: u16,
    pub ac_quantizer: u16,
    /// Optional row-major matrix weights with five fractional bits.
    pub matrix: Option<&'a [u8]>,
}

pub fn dequantize(coefficients: &mut [i32], config: DequantConfig<'_>) -> Result<(), Error> {
    bit_depth_index(config.bit_depth)?;
    let (width, height) = config.size.dimensions();
    let width = usize::from(width);
    let height = usize::from(height);
    let count = width.checked_mul(height).ok_or(Error::LimitExceeded)?;
    if coefficients.len() != count {
        return Err(Error::InvalidObu);
    }
    let transform_width = width.min(32);
    let transform_height = height.min(32);
    let transformed_count = transform_width
        .checked_mul(transform_height)
        .ok_or(Error::LimitExceeded)?;
    if config
        .matrix
        .is_some_and(|matrix| matrix.len() != transformed_count)
    {
        return Err(Error::InvalidObu);
    }
    let denominator = match config.size {
        TxSize::Tx32x32 | TxSize::Tx16x32 | TxSize::Tx32x16 | TxSize::Tx16x64 | TxSize::Tx64x16 => {
            2
        }
        TxSize::Tx64x64 | TxSize::Tx32x64 | TxSize::Tx64x32 => 4,
        _ => 1,
    };
    let minimum = -(1i64 << (7 + config.bit_depth));
    let maximum = (1i64 << (7 + config.bit_depth)) - 1;
    let original = coefficients;
    for row in 0..transform_height {
        for column in 0..transform_width {
            let compact_index = row * transform_width + column;
            let coefficient_index = row * width + column;
            let quantizer = if row == 0 && column == 0 {
                config.dc_quantizer
            } else {
                config.ac_quantizer
            };
            let adjusted = if let Some(matrix) = config.matrix {
                (u32::from(quantizer) * u32::from(matrix[compact_index]) + 16) >> 5
            } else {
                u32::from(quantizer)
            };
            let product = i64::from(original[coefficient_index])
                .checked_mul(i64::from(adjusted))
                .ok_or(Error::LimitExceeded)?;
            let sign = if product < 0 { -1 } else { 1 };
            let magnitude = product.unsigned_abs() & 0x00ff_ffff;
            let value =
                i64::try_from(magnitude / denominator).map_err(|_| Error::LimitExceeded)? * sign;
            original[coefficient_index] =
                i32::try_from(value.clamp(minimum, maximum)).map_err(|_| Error::LimitExceeded)?;
        }
    }
    for row in 0..height {
        for column in 0..width {
            if row >= transform_height || column >= transform_width {
                original[row * width + column] = 0;
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normative_quantizer_lookup_endpoints_cover_all_bit_depths() {
        assert_eq!(dc_quantizer(8, 0), Ok(4));
        assert_eq!(dc_quantizer(8, 255), Ok(1336));
        assert_eq!(dc_quantizer(10, 255), Ok(5347));
        assert_eq!(dc_quantizer(12, 255), Ok(21387));
        assert_eq!(ac_quantizer(8, 255), Ok(1828));
        assert_eq!(ac_quantizer(10, 255), Ok(7312));
        assert_eq!(ac_quantizer(12, 255), Ok(29247));
        assert_eq!(ac_quantizer(9, 0), Err(Error::InvalidObu));
        assert_eq!(dc_quantizer(8, -20), Ok(4));
        let hash = |table: &[[u16; 256]; 3]| {
            table
                .iter()
                .flatten()
                .fold(0xcbf2_9ce4_8422_2325u64, |hash, value| {
                    value.to_le_bytes().into_iter().fold(hash, |hash, byte| {
                        (hash ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01b3)
                    })
                })
        };
        assert_eq!(hash(&DC_QLOOKUP), 0x1af3_6c83_432a_b2ee);
        assert_eq!(hash(&AC_QLOOKUP), 0xfca3_11f1_451e_62de);
    }

    #[test]
    fn dequantization_applies_dc_ac_matrix_and_large_transform_denominator() {
        let mut coefficients = [2, -3, 0, 0];
        dequantize(
            &mut coefficients,
            DequantConfig {
                size: TxSize::Tx4x4,
                bit_depth: 8,
                dc_quantizer: 4,
                ac_quantizer: 8,
                matrix: None,
            },
        )
        .unwrap_err();

        let mut coefficients = [0i32; 16];
        coefficients[0] = 2;
        coefficients[1] = -3;
        let matrix = [32u8; 16];
        dequantize(
            &mut coefficients,
            DequantConfig {
                size: TxSize::Tx4x4,
                bit_depth: 8,
                dc_quantizer: 4,
                ac_quantizer: 8,
                matrix: Some(&matrix),
            },
        )
        .unwrap();
        assert_eq!(&coefficients[..2], &[8, -24]);

        let mut large = [0i32; 1024];
        large[0] = 8;
        dequantize(
            &mut large,
            DequantConfig {
                size: TxSize::Tx32x32,
                bit_depth: 8,
                dc_quantizer: 4,
                ac_quantizer: 4,
                matrix: None,
            },
        )
        .unwrap();
        assert_eq!(large[0], 16);
    }

    #[test]
    fn all_normative_quantizer_matrices_decode_exactly_from_compact_storage() {
        let mut hash = 0xcbf2_9ce4_8422_2325u64;
        for index in 0..100_320 {
            let value = decode_matrix_byte(index).unwrap();
            hash ^= u64::from(value);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
        assert_eq!(hash, 0x4934_4e39_b977_df34);
        let mut matrix = [0u8; 1024];
        assert_eq!(
            write_quantizer_matrix(0, false, TxSize::Tx4x4, &mut matrix),
            Ok(16)
        );
        assert_eq!(
            &matrix[..16],
            &[
                32, 43, 73, 97, 43, 67, 94, 110, 73, 94, 137, 150, 97, 110, 150, 200
            ]
        );
        write_quantizer_matrix(0, false, TxSize::Tx32x32, &mut matrix).unwrap();
        let square = matrix;
        write_quantizer_matrix(0, false, TxSize::Tx64x64, &mut matrix).unwrap();
        assert_eq!(matrix, square);
        assert_eq!(
            quantizer_matrix_value(15, false, TxSize::Tx4x4, 0),
            Err(Error::InvalidObu)
        );
    }

    #[test]
    fn matrix_selection_respects_plane_lossless_and_transform_type() {
        let quantization = Quantization {
            using_qmatrix: true,
            qm_y: 0,
            qm_u: 1,
            qm_v: 2,
            ..Quantization::default()
        };
        let mut matrix = [0u8; 16];
        assert_eq!(
            write_selected_quantizer_matrix(
                &quantization,
                false,
                0,
                TxType::DctDct,
                TxSize::Tx4x4,
                &mut matrix,
            ),
            Ok(Some(16))
        );
        assert_eq!(matrix[0], 32);
        assert_eq!(
            write_selected_quantizer_matrix(
                &quantization,
                true,
                0,
                TxType::DctDct,
                TxSize::Tx4x4,
                &mut matrix,
            ),
            Ok(None)
        );
        assert_eq!(
            write_selected_quantizer_matrix(
                &quantization,
                false,
                1,
                TxType::Identity,
                TxSize::Tx4x4,
                &mut matrix,
            ),
            Ok(None)
        );
    }
}
